#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Tunable constants for scheduling.
 *
 * These are simple knobs you can adjust (and rebuild) to better match
 * a particular CPU. INIT_VEC_WIDTH_HINT is only a hint: we cap it at
 * the natural vector size reported by Halide for the current target.
 */
constexpr int INIT_VEC_WIDTH_HINT = 8;

/* Array initialization translated to Halide. */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // -----------------------------------------------------------------
    // Algorithm
    // -----------------------------------------------------------------

    // x[i] = -999;
    Expr x_init_val = cast<num_t>(Expr(-999));
    init_x(i) = x_init_val;

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) to make j the fast-varying index.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));
    Expr zero   = cast<num_t>(Expr(0));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          zero);

    // -----------------------------------------------------------------
    // Schedule
    //
    // We make initialization data-parallel and vectorized for better
    // cache/memory bandwidth usage. This is outside the timed kernel,
    // so we can afford aggressive scheduling without affecting the
    // measured region, but it still improves start-up cost.
    // -----------------------------------------------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    vec_width = std::max(1, std::min(vec_width, INIT_VEC_WIDTH_HINT));

    // x and b are 1D; just vectorize across i.
    init_x
        .vectorize(i, vec_width);

    init_b
        .vectorize(i, vec_width);

    // L is 2D with j the innermost (fast) dimension. We parallelize
    // over rows (i) and vectorize across columns (j).
    init_L
        .reorder(j, i)         // j inner, i outer (already implied by L(j,i) but make explicit)
        .vectorize(j, vec_width)
        .parallel(i);

    // -----------------------------------------------------------------
    // Realization into user-provided buffers.
    // -----------------------------------------------------------------
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one (better cache locality for inner j-loop).
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b (these wrap the above Buffers).
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i (drives the triangular solve).
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // Bind ImageParams to our Buffers once. The Buffers themselves are
    // mutated on the host (for x), and since ImageParam refers to the
    // same underlying storage, each Halide realization will see the
    // updated values.
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation (per i):
    //
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // Because of the loop-carried dependence on x[0..i-1], the i-loop
    // must run sequentially. We therefore express a *single* forward-
    // substitution step in Halide, driven by an ImageParam view of x,
    // and execute that step from the host for each i.
    //
    // For each fixed i_param, we compute:
    //
    //   dot(i) = sum_{j=0..i-1} L[i][j] * x[j]
    //   x[i]   = (b[i] - dot(i)) / L[i][i]
    //
    // where L[i][j] is stored as L_param(j, i) for cache-friendly
    // access when j is the inner index.
    // -----------------------------------------------------------------

    // Reduction domain for the inner j-loop: r = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Dot product dot(i) = sum_j L[i][j] * x[j].
    Func dot("dot");
    Expr zero = cast<num_t>(Expr(0));
    dot() = zero;
    // L[i][j] is stored as L_param(j, i_param), j = r
    dot() += L_param(r, i_param) * x_param(r);

    // Final per-row solve step:
    Func solve_step("solve_step");
    solve_step() = (b_param(i_param) - dot()) / L_param(i_param, i_param);

    // Simple schedule for the per-row solve:
    //
    // - The computation is inherently scalar (0-D Funcs), so we just
    //   compute the reduction at root. The innermost j-loop runs over
    //   contiguous memory in L and x thanks to the L(j, i) layout,
    //   which already optimizes data locality.
    // - We keep the schedule simple to avoid introducing subtle
    //   reduction reordering; the outer loop over i (in C++) remains
    //   strictly sequential, preserving the original algorithm.
    dot.compute_root();

    Target target = get_host_target();
    solve_step.compile_jit(target);

    // Reuse a tiny 1-element Buffer for the scalar x[i] result to
    // avoid per-iteration allocation in realize().
    Halide::Buffer<num_t> xi_buf(1);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index for this forward-substitution step.
        i_param.set(i);

        // Realize scalar x[i] = solve_step() for this i into xi_buf(0)
        solve_step.realize(xi_buf);

        // Update x[i] on the host. Subsequent iterations will see
        // this updated value via x_param.
        x(i) = xi_buf(0);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
