    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          zero);

    // -------------------------
    // Scheduling for init funcs
    // -------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Bound i and j to the problem size so the compiler knows extents.
    init_x.bound(i, 0, n);
    init_b.bound(i, 0, n);
    init_L.bound(i, 0, n).bound(j, 0, n);

    // 1D initializations: parallelize across i, vectorize inner lane.
    {
        Var ix_outer("ix_outer"), ix_inner("ix_inner");
        init_x
            .split(i, ix_outer, ix_inner, vec_width)
            .vectorize(ix_inner)
            .parallel(ix_outer);
    }
    {
        Var ib_outer("ib_outer"), ib_inner("ib_inner");
        init_b
            .split(i, ib_outer, ib_inner, vec_width)
            .vectorize(ib_inner)
            .parallel(ib_outer);
    }

    // 2D initialization of L: j is contiguous, i is outer.
    // Parallelize across rows (i), and vectorize across j inside small tiles.
    {
        Var j_outer("j_outer"), j_inner("j_inner");
        const int tile_j = 64;  // good cache-line–friendly tile width on x64

        init_L
            .split(j, j_outer, j_inner, tile_j)
            .reorder(j_inner, j_outer, i)  // innermost loop over contiguous j_inner
            .vectorize(j_inner, vec_width)
            .parallel(i);
    }

    // Realize into the provided Buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
