    // For a fixed i:
    //
    //   sum = sum_{j = 0}^{i-1} L[i][j] * x[j];
    //   x[i] = (b[i] - sum) / L[i][i];
    //
    // We keep the i-loop on the host (sequential forward substitution),
    // and express the inner j-loop as a Halide reduction. This respects
    // the triangular dependency structure (x[i] depends on x[0..i-1]).
    // -----------------------------------------------------------------

    // Reduction domain over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Compute the dot product sum_{j<i} L[i][j] * x[j]
