    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Vectorize the reduction over j (r) for better use of SIMD.
    // Halide will generate a vectorized reduction kernel, handling tails.
    if (vec_width > 1) {
        dot.update().vectorize(r, vec_width);
