/* Optimized array initialization using Halide + schedule. */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // Cast constants once to Halide Expr of the right type.
    Expr minus_999 = cast<num_t>(Expr(-999));
    Expr zero      = cast<num_t>(Expr(0));
    Expr two       = cast<num_t>(Expr(2));
    Expr n_expr    = cast<num_t>(Expr(n));

    // x[i] = -999;
    init_x(i) = minus_999;

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) so that j is the fast-varying (x) dimension.
    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          zero);

    // ---- Scheduling for efficient initialization ----
    //
    // We choose a reasonable vector width based on the host target and
    // element type, and parallelize across outer loops. This improves
    // cache use and makes good use of available cores during init.
    Target target = get_host_target();
    const int vec = natural_vector_size(target, type_of<num_t>());

    // 1D vectors x and b: vectorize and parallelize over i.
    init_x.compute_root()
          .vectorize(i, vec)
          .parallel(i);

    init_b.compute_root()
          .vectorize(i, vec)
          .parallel(i);

    // 2D matrix L: parallelize over rows (i) and vectorize along columns (j).
    Var io("io"), ii("ii");
    const int tile_i = 64;  // tuning knob for cache behavior on large n

    init_L.compute_root()
          .split(i, io, ii, tile_i)
          .parallel(io)      // distribute rows across cores
          .vectorize(j, vec); // vector loads/stores along j

    // Materialize into the provided Buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one (row-major contiguous).
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data (vectorized + parallelized)
    init_array(n, L, x, b);

    // Bind ImageParams to our Buffers once; x will be updated in-place
    // on the host, but the underlying memory that x_param points to
    // remains valid across iterations.
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation (forward substitution):
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We keep the loop-carried dependency across i on the host
    // (as recommended for dynamic-programming-like recurrences):
    //   - Halide computes a single scalar x[i] for a given i_param.
    //   - The host loop iterates i and updates x[i] in-place.
    // -----------------------------------------------------------------

    // xi() holds the accumulated value b[i] - sum_{j<i} L[i][j] * x[j]
    Func xi("xi");
    // xi_div() holds the final x[i] = xi / L[i][i]
    Func xi_div("xi_div");

    // RDom over j = 0 .. i_param-1 (extent is data-dependent via Param)
    RDom r(0, i_param, "r");

    // Start from b[i].
    xi() = b_param(i_param);

    // Subtract contributions L[i][j] * x[j].
    // We rewrite the original "xi() -= ..." as "+= (-1) * ..." so that
    // the reduction is a pure sum; this makes it easier for Halide to
    // recognize it as an associative reduction internally if more
    // advanced scheduling (e.g., vectorization of the reduction) is
    // added later.
    Expr neg_one = cast<num_t>(Expr(-1));
    // Recall: L[i][j] is stored as L_param(j, i_param).
    xi() += neg_one * L_param(r, i_param) * x_param(r);

    // Divide by the diagonal entry L[i][i] (stored at L_param(i, i)).
    xi_div() = xi() / L_param(i_param, i_param);

    // JIT-compile the scalar pipeline once for the host target.
    Target target = get_host_target();
    xi_div.compile_jit(target);

    // Reuse a single scalar Buffer across all iterations to avoid
    // per-iteration heap allocation in realize().
    Halide::Buffer<num_t> xi_buf;

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i into the reusable buffer.
        xi_div.realize(xi_buf);

        // Update x[i] on the host
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
