    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We:
    //   * keep the i-loop on the host (sequential dependency),
    //   * express the inner j-loop as a Halide reduction, which allows
    //     Halide/LLVM to generate an efficient tight loop over j with
    //     good locality in L and x.
    // -----------------------------------------------------------------

    // dot() = sum_{j < i_param} L[i_param][j] * x[j]
    // Recall: L[i][j] is stored as L_param(j, i_param).
    Func dot("dot");
    RDom r(0, i_param, "r");

    dot() = cast<num_t>(Expr(0));
    dot() += L_param(r, i_param) * x_param(r);

    // x_i() = (b[i] - dot) / L[i][i]
    Func x_i("x_i");
    x_i() = (b_param(i_param) - dot()) / L_param(i_param, i_param);

    // -----------------------------------------------------------------
    // (Optional) Scheduling for the reduction:
    //
    // The reduction domain r is inherently sequential due to the scalar
    // accumulator dot(). We leave it to Halide/LLVM to generate an
    // optimized scalar loop here; explicit parallelization over r
    // would be illegal because of the loop-carried dependency in the
    // reduction. If desired, more advanced techniques (rfactor) could
    // be applied here, but they add complexity without changing the
    // asymptotic cost.
    // -----------------------------------------------------------------

    // JIT-compile the pipeline once for the host.
    Target target = get_jit_target_from_environment();
    x_i.compile_jit(target);

    // Reuse a tiny 0-D buffer for the scalar result to avoid per-iter
    // heap allocations in the inner loop.
    Halide::Buffer<num_t> xi_buf;  // 0-D buffer; size is implicit

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar x_i() for this i.
        //
        // Note: x_param refers directly to the same Buffer 'x' that we
        // are updating here. For the current i, all x[0..i-1] have
        // already been written by previous iterations and are visible
        // to the Halide pipeline, while x[i..n-1] are still at their
        // initialized values and never read.
        xi_buf = x_i.realize();

        // Update x[i] on the host with the freshly computed value.
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
