#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (e.g. N, DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (same role as trisolv.h)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide. */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(Expr(-999));

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) so that j (the inner loop index) is
    // the fastest-varying dimension in memory.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // Simple (one-time) scheduling: vectorize along the innermost dimension.
    // This is outside the timed region, but keeps initialization cheap.
    Target init_target = get_host_target();
    const int vec = init_target.natural_vector_size(type_of<num_t>());

    // x and b are 1D, contiguous in i
    init_x.vectorize(i, vec);
    init_b.vectorize(i, vec);

    // L is stored as L(j, i) with j contiguous in memory
    init_L
        .compute_root()
        .parallel(i)      // parallel over rows
        .vectorize(j, vec);

    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We express the j-loop as a reduction over RDom, and drive the
    // i-loop from the host, updating x one element at a time.
    //
    // The data dependencies are only along i (x[i] depends on x[0..i-1]),
    // so we keep i sequential on the host but aggressively vectorize
    // the inner j-reduction inside Halide.
    // -----------------------------------------------------------------

    Func xi("xi");         // accumulates b[i] - sum_{j<i} L[i][j]*x[j]
    Func xi_div("xi_div"); // final x[i] = xi / L[i][i]

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Start from b[i]
    xi() = b_param(i_param);

    // Subtract contributions L[i][j] * x[j] by doing an associative
    // sum of negative terms. Writing this as "+=" rather than "-="
    // makes it an explicit associative reduction, which Halide can
    // safely vectorize.
    // Recall: L[i][j] is stored as L_param(j, i_param).
    xi() += cast<num_t>(Expr(-1)) * L_param(r, i_param) * x_param(r);

    // Divide by the diagonal entry L[i][i] (stored as L_param(i, i))
    xi_div() = xi() / L_param(i_param, i_param);

    // Bind ImageParams to our Buffers (the pointers are reused across iterations).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // Tell Halide about the actual memory layout to enable dense vector loads.
    L_param.dim(0).set_stride(1);  // j is contiguous
    x_param.dim(0).set_stride(1);  // x[j] contiguous
    b_param.dim(0).set_stride(1);

    // -----------------------------
    // Scheduling for the reduction:
    // -----------------------------
    //
    // We want to vectorize the inner j-loop:
    //   for (int j = 0; j < i; ++j)
    //       acc += -L[i][j] * x[j];
    //
    // This is an associative (sum) reduction, so Halide can execute
    // multiple iterations of j in SIMD.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Vectorize the reduction over r (the j index).
    // Halide will internally split r into an outer scalar loop and an
    // inner vector loop of width vec_width, with a masked tail when
    // i_param is not a multiple of vec_width.
    if (vec_width > 1) {
        xi.update().vectorize(r, vec_width);
    }

    // JIT-compile the pipeline once for this target
    xi_div.compile_jit(target);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i (Halide reuses the same
        // internal allocation across calls, so this is allocation-free
        // after the first iteration).
        Halide::Buffer<num_t> xi_buf = xi_div.realize();

        // Update x[i] on the host; earlier entries x[0..i-1] are
        // already computed and were visible to the Halide pipeline
        // through x_param.
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
